const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const center = ee.Geometry.Point([98.9931, 18.7877]);
    const region = center.buffer(20000); // 20 km
    const periods = {
      Mar: {start: '2024-03-01', end: '2024-04-01'},
      May: {start: '2024-05-01', end: '2024-06-01'}
    };

    async function fetchMonthlyAOD(start, end) {
      const sources = ['MODIS/061/MOD08_M3', 'MODIS/061/MYD08_M3']; // Terra then Aqua
      let img = null, src = null, imgsCount = 0;
      for (const id of sources) {
        const col = ee.ImageCollection(id).filterDate(start, end);
        const size = await col.size().getInfo();
        if (size > 0) {
          img = ee.Image(col.first());
          src = id.split('/').pop();
          imgsCount = size;
          break;
        }
      }
      if (!img) return {status: 'C1', src: null, imgsCount: 0};

      const bandNames = await img.bandNames().getInfo();
      let band = null;
      if (bandNames.includes('AOD_550_Dark_Target_Deep_Blue_Combined_Mean')) {
        band = 'AOD_550_Dark_Target_Deep_Blue_Combined_Mean';
      } else if (bandNames.includes('Aerosol_Optical_Depth_Land_Ocean_Mean_Mean')) {
        band = 'Aerosol_Optical_Depth_Land_Ocean_Mean_Mean';
      } else {
        return {status: 'D', src, imgsCount};
      }

      const bandImg = img.select(band);
      let scale = await bandImg.projection().nominalScale().getInfo();
      if (!scale || !isFinite(scale)) scale = 1000;

      const countDict = await bandImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).getInfo();
      const count = countDict ? countDict[band] : 0;
      if (!count || count === 0) return {status: 'C2', src, imgsCount, band, count: 0};

      const meanDict = await bandImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).getInfo();
      const mean = meanDict ? meanDict[band] : null;
      if (mean === null || !isFinite(mean) || isNaN(mean)) return {status: 'C3', src, imgsCount, band, count};
      if (mean < 0 || mean > 5) return {status: 'C3', src, imgsCount, band, count, mean};

      return {status: 'OK', src, imgsCount, band, count, mean};
    }

    // 2. Data Acquisition & Checks
    const mar = await fetchMonthlyAOD(periods.Mar.start, periods.Mar.end);
    const may = await fetchMonthlyAOD(periods.May.start, periods.May.end);

    console.log('Region: Chiang Mai, TH (20km buffer)');
    console.log(`Mar2024 src: ${mar.src || 'None'}, imgs: ${mar.imgsCount}`);
    console.log(`May2024 src: ${may.src || 'None'}, imgs: ${may.imgsCount}`);

    // Handle error cases
    if (mar.status === 'C1' || may.status === 'C1') { console.log('C1'); return; }
    if (mar.status === 'C2' || may.status === 'C2') { console.log('C2'); return; }
    if (mar.status === 'C3' || may.status === 'C3') { console.log('C3'); return; }
    if (mar.status === 'D' || may.status === 'D') { console.log('D'); return; }

    // 3. Processing & Output
    console.log(`Mar AOD: ${mar.mean.toFixed(3)} (px:${mar.count})`);
    console.log(`May AOD: ${may.mean.toFixed(3)} (px:${may.count})`);
    const diff = mar.mean - may.mean;
    console.log(`Diff (Mar - May): ${diff.toFixed(3)}`);

    // 4. Final Answer
    if (!isFinite(diff)) { console.log('C3'); return; }
    console.log(diff > 0 ? 'A' : 'B');
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
